  const R=SVB.ROLE_T[svRole()]||'', nm=SVU.name||SVU.email||'';
  document.querySelectorAll('[data-me-name]').forEach(el=>el.textContent=nm);
  document.querySelectorAll('[data-me-role]').forEach(el=>el.textContent=R);
