  const U=await svUseLoad()||[];
  const warn=U.filter(u=>u.ai24>=40||u.flagN>0), idle=U.filter(u=>u.active&&u.role!=='viewer'&&u.role!=='admin'&&(!u.last_seen||Date.now()-new Date(u.last_seen)>14*864e5));
