SV4_HUB.wissen.tabs.push(['ki','Mit KI arbeiten']); SV4_OF.ki='wissen';
Object.assign(SV_PAGES,{ki:['Wissen','Mit der eigenen KI arbeiten: was verbinden, wie, fertige Aufträge']});
