  Promise.resolve(SVB.sb.rpc('spiel_quellen',{p_von:sv50Start(),p_bis:trToday()})).then(r=>{ SVM.q31Busy=false; if(r&&!r.error){ SVM.q31=new Map((r.data||[]).map(x=>[String(x.datum),x])); try{ after&&after(); }catch(e){} } },()=>{ SVM.q31Busy=false; });
