{ const m=/^#spieler=([A-Za-z0-9_:.%-]{1,160})$/.exec(location.hash||''); if(m){ try{ MN31_ZIEL.id=decodeURIComponent(m[1]); history.replaceState(history.state,'',location.pathname+location.search); }catch(e){} } }
